  else {
    if (dir == 0)
      return (is_lower? ser_gk_collisionless_flux_boundary_surfx_lower_nonperiodic_kernels
                      : ser_gk_collisionless_flux_boundary_surfx_upper_nonperiodic_kernels)[cv_index[cdim].vdim[vdim]].kernels[poly_order];
