+static void
+first_rhs_summary(const char *name, const struct gkyl_array *arr,
+  const struct gkyl_range *local, const struct gkyl_range *local_ext)
+{
+  double sum = 0.0, sumsq = 0.0, maxabs = 0.0;
+  long n = 0;
+  struct gkyl_range_iter iter;
+  gkyl_range_iter_init(&iter, local);
+  while (gkyl_range_iter_next(&iter)) {
+    const double *data = gkyl_array_cfetch(arr, gkyl_range_idx(local_ext, iter.idx));
+    for (size_t c = 0; c < arr->ncomp; ++c) {
+      double v = data[c];
+      sum += v;
+      sumsq += v*v;
+      maxabs = GKYL_MAX2(maxabs, fabs(v));
+      n += 1;
+    }
+  }
+  fprintf(stderr, "FIRST_RHS %s n=%ld sum=% .17e sumsq=% .17e maxabs=% .17e\\n",
+    name, n, sum, sumsq, maxabs);
+}
