 *
 * @param base Base range wrt which edge overlap is checked
 * @param targ Target range to check
 * @return direction and edge. Returned struct eloc is set
 *   to GKYL_NO_EDGE if ranges dont match.
 */
struct gkyl_range_dir_edge gkyl_range_edge_match(const struct gkyl_range *base,
  const struct gkyl_range *targ);

/**
 * General indexing function. Returns linear index into the index
 * range mapped by 'range'.
 *
 * @param range Range object to index
 * @param idx Index for which to compute linear index
 */
GKYL_CU_DH
static inline long
gkyl_range_idx(const struct gkyl_range* range, const int *idx)
{
#define RI(...) gkyl_ridx(*range, __VA_ARGS__)
  switch (range->ndim) {
    case 0:
      return range->ac[0];
      break;    
    case 1:
      return RI(idx[0]); 
      break;
    case 2:
      return RI(idx[0], idx[1]);
      break;
    case 3:
      return RI(idx[0], idx[1], idx[2]);
      break;
    case 4:
      return RI(idx[0], idx[1], idx[2], idx[3]);
      break;
    case 5:
      return RI(idx[0], idx[1], idx[2], idx[3], idx[4]);
      break;
    case 6:
      return RI(idx[0], idx[1], idx[2], idx[3], idx[4], idx[5]);
      break;
    case 7:
      return RI(idx[0], idx[1], idx[2], idx[3], idx[4], idx[5], idx[6]);
      break;
  }
  return 0;
#undef RI
}

/**
 * Compute offset given relative index. So for a 2D range, idx[2] = {1,
 * 0} will compute the relative offset from {i, j} to {i+1, j} in the
 * mapping from indices to a linear integer space.
 *
 * @param range Range to find offset in.
 * @param idx Relative index for offset calculation
 * @return Relatice offset to idx.
 */
GKYL_CU_DH
  // Initialize projection routine for initial conditions.
  if (gks->info.init_from_file.type == 0) {
    gk_species_projection_init(app, gks, gks->info.projection, &gks->proj_init);
  }
  else {
    gk_species_file_import_init(app, gks, gks->info.init_from_file);
  }

  // Create skin/ghost ranges.
  for (int dir=0; dir<cdim; ++dir) {
    gkyl_skin_ghost_ranges(&gks->local_lower_skin[dir], &gks->local_lower_ghost[dir],
      dir, GKYL_LOWER_EDGE, &gks->local_ext, ghost);
    gkyl_skin_ghost_ranges(&gks->local_upper_skin[dir], &gks->local_upper_ghost[dir],
      dir, GKYL_UPPER_EDGE, &gks->local_ext, ghost);
    gkyl_skin_ghost_ranges(&gks->global_lower_skin[dir], &gks->global_lower_ghost[dir],
      dir, GKYL_LOWER_EDGE, &gks->global_ext, ghost); 
    gkyl_skin_ghost_ranges(&gks->global_upper_skin[dir], &gks->global_upper_ghost[dir],
      dir, GKYL_UPPER_EDGE, &gks->global_ext, ghost);
  }

  // Create a local range extended in the BC dir (for TS BCs).
  int par_dir = app->cdim-1;
  int ndim = gks->local.ndim;
  int lower_bcdir_ext[ndim], upper_bcdir_ext[ndim];
  for (int i=0; i<ndim; i++) {
    lower_bcdir_ext[i] = gks->local.lower[i];
    upper_bcdir_ext[i] = gks->local.upper[i];
  }
  lower_bcdir_ext[par_dir] = gks->local_ext.lower[par_dir];
  upper_bcdir_ext[par_dir] = gks->local_ext.upper[par_dir];
  gkyl_sub_range_init(&gks->local_par_ext, &gks->local_ext, lower_bcdir_ext, upper_bcdir_ext);

  if (gk_app_inp->geometry.has_LCFS) {
    // Simulation spans the last-closed flux surface (LCFS). Create core and SOL global ranges.
    int idx_LCFS_lo = app->gk_geom->idx_LCFS_lo;
    // Length of lower and upper x ranges (one is core, the other SOL).
    int len_lo = idx_LCFS_lo;
    int len_up = gks->global.upper[0]-len_lo;
    // Lower and upper x ranges.
    struct gkyl_range *global_lo_r, *global_ext_lo_r, *global_up_r, *global_ext_up_r;
    struct gkyl_range *local_lo_r, *local_ext_lo_r, *local_up_r, *local_ext_up_r;
    struct gkyl_range *local_lower_skin_par_lo_r, *local_upper_skin_par_lo_r,
                      *local_lower_ghost_par_lo_r, *local_upper_ghost_par_lo_r;
    struct gkyl_range *local_lower_skin_par_up_r, *local_upper_skin_par_up_r,
                      *local_lower_ghost_par_up_r, *local_upper_ghost_par_up_r;
    if (app->gk_geom->geqdsk_sign_convention == 0) {
      // x increases towards SOL.
      global_lo_r                = &gks->global_core;
      global_up_r                = &gks->global_sol;
      global_ext_lo_r            = &gks->global_ext_core;
      global_ext_up_r            = &gks->global_ext_sol;
      local_lo_r                 = &gks->local_core;
      local_up_r                 = &gks->local_sol;
      local_ext_lo_r             = &gks->local_ext_core;
      local_ext_up_r             = &gks->local_ext_sol;
      local_lower_skin_par_lo_r  = &gks->local_lower_skin_par_core;
      local_lower_ghost_par_lo_r = &gks->local_lower_ghost_par_core;
      local_lower_skin_par_up_r  = &gks->local_lower_skin_par_sol;
      local_lower_ghost_par_up_r = &gks->local_lower_ghost_par_sol;
      local_upper_skin_par_lo_r  = &gks->local_upper_skin_par_core;
      local_upper_ghost_par_lo_r = &gks->local_upper_ghost_par_core;
    for (int dir = 0; dir<cdim; ++dir) {
      gkyl_copy_int_arr(pdim, idx, idxL);
      idxL[dir] = idx[dir] - 1;
      long locL = gkyl_range_idx(phase_range, idxL);
      const double *fL = gkyl_array_cfetch(fin, locL);
      const double *fR = gkyl_array_cfetch(fin, loc_phase);

      const struct gkyl_dg_surf_geom *dgs = gkyl_dg_geom_get_surf(up->dg_geom, dir, idx);
      const struct gkyl_gk_dg_surf_geom *gkdgs = gkyl_gk_dg_geom_get_surf(up->gk_dg_geom, dir, idx);
      cflrate_d[0] += up->flux_surf[dir](xc, up->phase_grid.dx, 
        vmap_d, vmapSq_d, up->charge, up->mass,
        dgs, gkdgs,
        bmag_d, phi_d,  fL, fR, flux_surf_d);


      // If the phase space index is at the local configuration space upper value, we
      // we are at the configuration space upper edge and we also need to evaluate 
      // alpha = +1 to avoid evaluating the geometry information in the ghost cells 
      // where it is not defined when computing the final surface alpha we need
      // (since the surface alpha array stores only the *lower* surface expansion)
      if (idx[dir] == phase_range->upper[dir]) {
        gkyl_copy_int_arr(pdim, idx, idx_edge);
        idx_edge[dir] = idx_edge[dir]+1;
        long loc_conf_ext = gkyl_range_idx(conf_ext_range, idx_edge);
        long loc_phase_ext = gkyl_range_idx(phase_ext_range, idx_edge);

        double *cflrate_ext_d = gkyl_array_fetch(cflrate, loc_phase_ext);
        const double *fL = gkyl_array_cfetch(fin, loc_phase);
        const double *fR = gkyl_array_cfetch(fin, loc_phase_ext);
        const struct gkyl_dg_surf_geom *dgs = gkyl_dg_geom_get_surf(up->dg_geom, dir, idx_edge);
        const struct gkyl_gk_dg_surf_geom *gkdgs = gkyl_gk_dg_geom_get_surf(up->gk_dg_geom, dir, idx_edge);

        double* flux_surf_ext_d = gkyl_array_fetch(flux_surf, loc_phase_ext);
        cflrate_ext_d[0] += up->flux_edge_surf[dir](xc, up->phase_grid.dx, 
          vmap_d, vmapSq_d, up->charge, up->mass,
          dgs, gkdgs,
          bmag_d, phi_d, fL, fR, flux_surf_ext_d);
      }  
    }
  }

  gkyl_range_iter_init(&iter, &vpar_range);
  while (gkyl_range_iter_next(&iter)) {
    gkyl_copy_int_arr(pdim, iter.idx, idx);

    for (int d=cdim; d<pdim; d++) idx_vel[d-cdim] = iter.idx[d];

