void
gkyl_range_extend(struct gkyl_range *erng,
  const struct gkyl_range* range, const int *elo, const int *eup)
{
  int ndim = range->ndim;
  int lo[GKYL_MAX_DIM] = {0}, up[GKYL_MAX_DIM] = {0};

  for (int i=0; i<ndim; ++i) {
    lo[i] = range->lower[i]-elo[i];
    up[i] = range->upper[i]+eup[i];
  }
  gkyl_range_init(erng, ndim, lo, up);
}

void
gkyl_range_perp_extend(struct gkyl_range *erng, int dir,
  const struct gkyl_range* rng, const int *elo, const int *eup)
{
  int ndim = rng->ndim;
  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, &local_sub);
  while (gkyl_range_iter_next(&iter)) {
    long lidx1 = gkyl_range_idx(&local_sub, iter.idx);
    long lidx2 = gkyl_range_idx(&local_ext, iter.idx);

    TEST_CHECK( lidx2 == lidx1 );
  }
}

void test_extend(void)
{
  int lo[] = {1, 1}, up[] = { 4, 8 };

  struct gkyl_range range;
  gkyl_range_init(&range, 2, lo, up);

  int elo[] = { 0, 1 }, eup[] = { 1, 2 };
  struct gkyl_range ext_range;
  gkyl_range_extend(&ext_range, &range, elo, eup);

  TEST_CHECK( ext_range.volume == (4+1)*(8+1+2) );

  TEST_CHECK( ext_range.lower[0] == 1 );
  TEST_CHECK( ext_range.upper[0] == 5 );

  TEST_CHECK( ext_range.lower[1] == 0 );
  TEST_CHECK( ext_range.upper[1] == 10 );
}

